import os
import sys
import subprocess
import hashlib
import re
from pathlib import Path

def get_workspace_root():
    return Path(__file__).parent.resolve()

def validate_path(base_path: Path, target_path: str) -> Path:
    resolved_target = (base_path / target_path).resolve()
    if not str(resolved_target).startswith(str(base_path.resolve())):
        raise ValueError(f"Invalid path traversal attempt: {target_path}")
    return resolved_target

def clone_repository(repo_url: str, target_dir: Path):
    if not re.match(r'^https?://', repo_url):
        raise ValueError(f"Invalid URL format: {repo_url}")

    if target_dir.exists():
        return

    try:
        subprocess.run(
            ["git", "clone", repo_url, str(target_dir)],
            check=True,
            capture_output=True,
            text=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to clone repository: {e.stderr}")

def generate_cron_config(output_path: Path, timestamp: str):
    cron_content = f"# Cron Configuration\n# Generated: {timestamp}\n\n# Example task\n0 * * * * /usr/bin/python3 /workspace/scripts/health_check.py\n"
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(cron_content)

def append_to_bashrc(bashrc_path: Path, env_vars: dict, aliases: list):
    if not bashrc_path.exists():
        bashrc_path.touch()

    with open(bashrc_path, 'a', encoding='utf-8') as f:
        for key, value in env_vars.items():
            if not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', key):
                continue
            f.write(f'export {key}="{value}"\n')

        for alias_name, alias_cmd in aliases:
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', alias_name):
                continue
            f.write(f'alias {alias_name}="{alias_cmd}"\n')

def main():
    workspace_root = get_workspace_root()
    boot_dir = validate_path(workspace_root, "boot")
    plugins_dir = validate_path(workspace_root, "plugins")
    cron_dir = validate_path(workspace_root, "cron")

    boot_dir.mkdir(parents=True, exist_ok=True)
    plugins_dir.mkdir(parents=True, exist_ok=True)
    cron_dir.mkdir(parents=True, exist_ok=True)

    repos = [
        ("https://github.com/example/boot-repo.git", "boot/boot-repo"),
        ("https://github.com/example/plugin-core.git", "plugins/plugin-core"),
    ]

    for url, path in repos:
        target = validate_path(workspace_root, path)
        clone_repository(url, target)

    timestamp = subprocess.check_output(["date", "+%Y-%m-%d %H:%M:%S"]).decode().strip()
    cron_file = cron_dir / "config.cron"
    generate_cron_config(cron_file, timestamp)

    env_vars = {
        "APP_SECRET_KEY": os.getenv("APP_SECRET_KEY", ""),
        "DB_PASSWORD": os.getenv("DB_PASSWORD", "")
    }

    aliases = [
        ("start-app", "python3 /workspace/boot/boot-repo/main.py"),
        ("reload-plugins", "python3 /workspace/plugins/plugin-core/reload.py")
    ]

    bashrc_path = Path.home() / ".bashrc"
    append_to_bashrc(bashrc_path, env_vars, aliases)

if __name__ == "__main__":
    main()
